/**
 * Loads the campsite document [campsiteId] from Firestore and passes it to
 * [onResult], or null if it is missing or can't be read.
 */
private fun loadCampsiteForAdmin(campsiteId: String, onResult: (Campsite?) -> Unit) {
    if (campsiteId.isBlank()) return onResult(null)
    FirebaseFirestore.getInstance().collection("campsites").document(campsiteId).get()
        .addOnSuccessListener { doc -> onResult(runCatching { doc.toObject(Campsite::class.java) }.getOrNull()) }
        .addOnFailureListener {
            Log.e("AdminRatings", "Could not load campsite", it)
            onResult(null)
        }
}

/**
 * Lists every rating of one campsite, newest first, and lets an admin remove a
 * rating after confirming. Removing a rating updates the campsite's average.
 *
 * @param navController used to go back to the admin campsite list.
 * @param campsiteId ID of the campsite whose ratings are shown.
 * @param ratingRepository where ratings are stored.
 * @param loadCampsite loads the campsite, to show its name and current average.
 */
@Composable
fun AdminCampsiteRatingsScreen(
    navController: NavController,
    campsiteId: String,
    ratingRepository: RatingRepository = remember { FirestoreRatingRepository() },
    loadCampsite: (String, (Campsite?) -> Unit) -> Unit = ::loadCampsiteForAdmin,
) {
    val backgroundColor = Color(0xFFFEFAE0)
    val buttonColor = Color(0xFF283618)

    var campsite by remember { mutableStateOf<Campsite?>(null) }
    var ratings by remember { mutableStateOf<List<CampsiteRating>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    var loadError by remember { mutableStateOf<String?>(null) }
    var reloadKey by remember { mutableStateOf(0) }

    var pendingRemoval by remember { mutableStateOf<CampsiteRating?>(null) }
    var removingUserId by remember { mutableStateOf<String?>(null) }
    var message by remember { mutableStateOf<String?>(null) }
    var actionError by remember { mutableStateOf<String?>(null) }

    LaunchedEffect(campsiteId, reloadKey) {
        isLoading = true
        loadError = null
        loadCampsite(campsiteId) { campsite = it }
        ratingRepository.getRatings(
            campsiteId,
            onSuccess = {
                ratings = it
                isLoading = false
            },
            onFailure = {
                Log.e("AdminRatings", "Could not load ratings", it)
                loadError = "Could not load ratings."
                isLoading = false
            },
        )
    }

    fun remove(rating: CampsiteRating) {
        if (removingUserId != null) return
        removingUserId = rating.userId
        message = null
        actionError = null
        ratingRepository.removeRating(
            campsiteId,
            rating.userId,
            onSuccess = { totals ->
                removingUserId = null
                ratings = ratings.filterNot { it.userId == rating.userId }
                campsite = campsite?.copy(
                    rating = totals.average,
                    ratingSum = totals.sum,
                    ratingCount = totals.count,
                )
                message = "Removed ${displayRaterName(rating)}'s ${rating.stars}-star rating."
            },
            onFailure = {
                removingUserId = null
                actionError = it.message ?: "Could not remove the rating."
                // The rating may already be gone (e.g. another admin removed it); reload to show what's stored.
                reloadKey++
            },
        )
    }

    pendingRemoval?.let { rating ->
        AlertDialog(
            onDismissRequest = { pendingRemoval = null },
            title = { Text("Remove this rating?") },
            text = {
                Text(
                    "${displayRaterName(rating)}'s ${rating.stars}-star rating will be deleted " +
                        "and the campsite's average recalculated. This can't be undone."
                )
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        pendingRemoval = null
                        remove(rating)
                    },
                    modifier = Modifier.testTag("confirmRemoveRatingButton"),
                ) { Text("Remove", color = Color.Red) }
            },
            dismissButton = {
                TextButton(onClick = { pendingRemoval = null }) { Text("Cancel") }
            },
        )
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(backgroundColor)
            .statusBarsPadding()
            .navigationBarsPadding()
            .padding(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Box(modifier = Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RoundedCornerShape(8.dp),
                colors = ButtonDefaults.buttonColors(containerColor = buttonColor, contentColor = Color.White),
                modifier = Modifier.align(Alignment.CenterStart).testTag("backButton"),
            ) {
                Text("< Back")
            }
            Text("Ratings", fontSize = 35.sp, color = buttonColor, modifier = Modifier.testTag("adminRatingsHeader"))
        }

        Spacer(modifier = Modifier.height(12.dp))
        campsite?.let {
            Text(it.name.ifBlank { "(unnamed)" }, fontSize = 20.sp, color = buttonColor)
            Text(
                RatingPolicy.summary(RatingPolicy.totalsOf(it)),
                fontSize = 16.sp,
                color = buttonColor,
                modifier = Modifier.testTag("adminRatingsSummary"),
            )
        }
        Spacer(modifier = Modifier.height(12.dp))

        actionError?.let {
            Text(it, color = Color.Red, modifier = Modifier.testTag("adminRatingsError"))
            Spacer(modifier = Modifier.height(8.dp))
        }
        message?.let {
            Text(it, color = buttonColor, modifier = Modifier.testTag("adminRatingsMessage"))
            Spacer(modifier = Modifier.height(8.dp))
        }

        Box(modifier = Modifier.weight(1f).fillMaxWidth()) {
            when {
                isLoading -> CircularProgressIndicator(
                    color = buttonColor,
                    modifier = Modifier.align(Alignment.Center),
                )
                loadError != null -> Column(
                    modifier = Modifier.align(Alignment.Center),
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(loadError!!, color = Color.Red)
                    Spacer(modifier = Modifier.height(8.dp))
                    Button(
                        onClick = { reloadKey++ },
                        colors = ButtonDefaults.buttonColors(containerColor = buttonColor, contentColor = Color.White),
                        modifier = Modifier.testTag("retryRatingsButton"),
                    ) { Text("Retry") }
                }
                ratings.isEmpty() -> Text(
                    "This campsite has no ratings.",
                    fontSize = 18.sp,
                    color = buttonColor,
                    modifier = Modifier.align(Alignment.Center).testTag("noRatingsText"),
                )
                else -> LazyColumn(
                    modifier = Modifier.fillMaxSize().testTag("adminRatingsList"),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    items(ratings, key = { it.userId }) { rating ->
                        RatingRow(
                            rating = rating,
                            buttonColor = buttonColor,
                            isRemoving = removingUserId == rating.userId,
                            removeEnabled = removingUserId == null,
                            onRemove = { pendingRemoval = rating },
                        )
                    }
                }
            }
        }
    }
}

/** Name shown for a rater, falling back to "Unnamed user". */
private fun displayRaterName(rating: CampsiteRating): String =
    rating.raterName.trim().ifEmpty { "Unnamed user" }

/** One rating: who gave it, how many stars, when, and a Remove button. */
@Composable
private fun RatingRow(
    rating: CampsiteRating,
    buttonColor: Color,
    isRemoving: Boolean,
    removeEnabled: Boolean,
    onRemove: () -> Unit,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, buttonColor)
            .padding(12.dp)
            .testTag("adminRating_${rating.userId}"),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(displayRaterName(rating), fontSize = 18.sp, fontWeight = FontWeight.Bold, color = buttonColor)
            Text(
                "★".repeat(rating.stars) + "☆".repeat((RatingPolicy.MAX_STARS - rating.stars).coerceAtLeast(0)),
                fontSize = 20.sp,
                color = buttonColor,
            )
            Text(
                listOfNotNull(
                    rating.updatedAt?.let { SimpleDateFormat("MMM d, yyyy", Locale.US).format(it) },
                    "ID ${rating.userId.take(8)}",
                ).joinToString(" · "),
                fontSize = 12.sp,
                color = buttonColor.copy(alpha = 0.7f),
            )
        }
        Button(
            onClick = onRemove,
            enabled = removeEnabled,
            shape = RoundedCornerShape(8.dp),
            colors = ButtonDefaults.buttonColors(containerColor = Color.Red),
            modifier = Modifier.testTag("removeRating_${rating.userId}"),
        ) {
            Text(if (isRemoving) "..." else "Remove", color = Color.White)
        }
    }
}

